import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
// --- Google Fonts Loader (Standard Pattern) ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Sub-components for Scenes ---

const BeachScene: React.FC<{
  width: number;
  height: number;
  sunColor: string;
  oceanColor: string;
  skyColor: string;
}> = ({ width, height, sunColor, oceanColor, skyColor }) => {
  const frame = useCurrentFrame();
  
  // Gentle wave motion
  const waveOffset = Math.sin(frame / 20) * (height * 0.05);
  const sunY = interpolate(frame % 150, [0, 75, 150], [0, -20, 0], { extrapolateRight: "clamp" });

  return (
    <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: skyColor, overflow: "hidden" }}>
      {/* Sun */}
      <div
        style={{
          position: "absolute",
          top: height * 0.2 + sunY,
          right: width * 0.2,
          width: width * 0.2,
          height: width * 0.2,
          backgroundColor: sunColor,
          borderRadius: "50%",
        }}
      />
      {/* Ocean */}
      <div
        style={{
          position: "absolute",
          bottom: -20,
          left: -10,
          width: "120%",
          height: "40%",
          backgroundColor: oceanColor,
          transform: `translateY(${waveOffset}px) rotate(${Math.sin(frame/40)*2}deg)`,
          borderRadius: "100% 100% 0 0",
        }}
      />
    </div>
  );
};

